package org.credivel.news;
import jakarta.validation.Valid;import org.springframework.data.domain.Page;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/news") public class NewsController{private final NewsService s;public NewsController(NewsService x){s=x;}@GetMapping public Page<NewsResponse> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="12")int size){if(page<0||size<1||size>50)throw new IllegalArgumentException();return s.list(page,size);}@GetMapping("/slug/{slug}")public NewsResponse get(@PathVariable String slug){return s.bySlug(slug);}@GetMapping("/{id}")public NewsResponse get(@PathVariable Long id){return s.byId(id);}@PostMapping public ResponseEntity<NewsResponse> create(@Valid @RequestBody NewsRequest r){return ResponseEntity.status(HttpStatus.CREATED).body(s.create(r));}@PutMapping("/{id}")public NewsResponse update(@PathVariable Long id,@Valid @RequestBody NewsRequest r){return s.update(id,r);}@DeleteMapping("/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@PathVariable Long id){s.delete(id);}}
